      SUBROUTINE VERNCC     CALCULATES BEAM CENTROID DISPLACEMENT AND TRANSFER MATRIX FOR C     A VERNIER MAGNETCC ----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'R.CIN'C      COD(1) = - 0.5*AL*L      COD(2) = - AL      R(1,2) = L      R(3,4) = L      R(1,6) = 0.5*AL*L      R(2,6) = AL      R(5,2) = 0.5*H0*L**2      RETURN      END